import type { ThreadStateSnapshot } from '../../../../shared/thread-state';
import type { components } from './api-types';
import type { AvatarProfileRef } from './avatar-profile-ref';
import type { MessageTomb } from '../../../../shared/message-tomb';

/**
 * API types are generated by openapi-typescript from the backend's /api/v1/docs-json (api-types.ts);
 * this file re-exports them under aliases so each service/component's `from './model'` import stays stable.
 * After changing a backend DTO, run `npm run gen:api` to regenerate.
 *
 * StandardResponse<T> is kept hand-written: the generated ApiResult.data is `unknown` (generic erasure),
 * so it cannot replace the frontend's generic envelope (http.post<StandardResponse<Message[]>>).
 */
type S = components['schemas'];

/** Federated media localize status values — the stable wire format (backend serializeBody + MEDIA_STATUS
 *  SSE frame + the attachMediaStatus query field carry these exact strings). A const object so every
 *  reference is `MEDIA_STATUS.READY` (typed + refactor-safe), not a bare literal scattered around.
 *  Mirrors the backend's src/common/media-status.ts. 'ready' = bytes local + authz (URL serves 200);
 *  'failed' = localize failed (URL 4xx, retryable); pending/downloading are durable backend states. */
export const MEDIA_STATUS = {
  READY: 'ready',
  PENDING: 'pending',
  DOWNLOADING: 'downloading',
  FAILED: 'failed',
} as const;
export type MediaStatus = (typeof MEDIA_STATUS)[keyof typeof MEDIA_STATUS];

export type User = S['UserResponseDto'];
export type SelfAccount = S['SelfAccountResponseDto'];
export type ContactCardTarget = {
  account: string;
  namespaceId: number;
  profileRev: number;
};
/** The wire payload for `send-contact-card`. The client sends only the identity
 * coordinates the server cannot derive: account, namespaceId, and profileRev.
 * The server resolves the display `domain` from `IdentityNamespace`. */
export type ContactCardSendTarget = ContactCardTarget;
/** The contact picker's selection result: pinned identity coordinates plus the
 *  already-materialized display fields used for the optimistic preview. The
 *  server freezes the authoritative card content (domain, root key, avatar)
 *  from the target when the message is sent. */
export interface ContactCardPreview {
  target: ContactCardTarget;
  account: string;
  name: string;
  bio: string;
}
export interface MessageCreator {
  account: string;
  namespaceId: number;
}
export type Message = Omit<
  S['MessageResponseDto'],
  'contentType' | 'mediaStatus' | 'creator'
> & {
  contentType: S['MessageResponseDto']['contentType'];
  /** Projected author coordinate; never use it to reconstruct a profile namespace. */
  namespaceId: number;
  /** Immutable author profile selected when this message was committed. */
  profileRev: number;
  /** Sender identity selected by this message. Domain is presentation metadata and may be absent on history rows. */
  creator: MessageCreator;
  /** Local-only corrections to participant revisions in a SYSTEM row, keyed by [namespaceId, account].
   * The server content remains immutable; cache merges preserve corrections for the same content. */
  localSystemProfileRevs?: Record<string, number>;
  /** Federated media localize status (absent = ready). Carried on query-messages rows; one mounted-message
   * service reconciles mount, reconnect and media-status updates. */
  mediaStatus?: MediaStatus;
};
export type MessageQueryRow = Message | MessageTomb;

/** A tomb can enter the cache before its message identity. Only identified tombs are timeline rows. */
export function isRenderableMessageTomb(
  row:
    | MessageQueryRow
    | import('../../../../shared/message-tomb').MessageDeletionMarker,
): row is MessageTomb {
  return row.contentType === 'TOMB' && 'creator' in row;
}

/** Identity coordinates are already canonical. Locality is determined only by namespace zero;
 * the domain always remains the real federation domain supplied by the server. */
export function localSubjectIdentity<T extends { namespaceId: number }>(
  identity: T,
): T {
  return identity;
}

/** Display mirror of the selected immutable profile revision: name, bio and
 * avatarDigest are one snapshot group per rev. Avatar bytes live in the shared
 * digest store and are committed together with the snapshot, so the digest is
 * equivalent to the bytes being present. Not part of thread rows. */
export interface ThreadProfileSlot {
  name: string;
  bio: string;
  avatarDigest: string | null;
}

/** Group-owned state persisted in its own group_meta row. */
export interface GroupMetaSlot {
  memberCount: number;
  /** Applied Group Meta position. */
  groupMetaFeedId: string;
  /** Tri-state announcement: a null feedId means unknown; a set feedId with null
   * text is a known clear; both set carry the current announcement. */
  announcementFeedId: string | null;
  announcementText: string | null;
  /** Server copy time of the current announcement (epoch milliseconds). */
  announcementCreatedAt: number | null;
  /** Origin publication time of the current announcement; null on origin servers. */
  announcementOriginCreatedAt: number | null;
  /** Fixed full-recovery boundary; null outside a resumable Group Meta rebuild. */
  recoveryThrough: string | null;
  recoveryAnnouncementFeedId: string | null;
  recoveryAnnouncementText: string | null;
  recoveryAnnouncementCreatedAt: number | null;
  recoveryAnnouncementOriginCreatedAt: number | null;
}

/** Cross-dialog user reference: display fields plus the identity namespace coordinate. Unlike
 * ThreadPeerUser this is a transient hand-off between dialogs, not a persisted row. `domain` is
 * optional presentation data supplied by card/facts sources; display resolution goes through the
 * namespace binding cache, and the domain only feeds functional address re-fill (search). */
export interface UserRef {
  id: number;
  account: string;
  name: string;
  /** Display data supplied directly by identity lookup endpoints, not a profile-store reference. */
  avatar: string;
  bio: string;
  namespaceId: number;
  isGroup: boolean;
  domain?: string;
}

/** Known identities carry a pinned demand reference, never an avatar string. */
export interface ProfileUserRef extends Omit<UserRef, 'avatar'> {
  profile: AvatarProfileRef;
}

export type InviteSubject = UserRef | ProfileUserRef;

export function messageCreatorKey(creator: MessageCreator): string {
  return JSON.stringify([creator.namespaceId, creator.account]);
}

/** Message sender keys identify the immutable subject selected by a message row.
 * Domains are presentation metadata resolved separately from profile namespace bindings. */
export function parseUserIdentityKey(key: string): {
  account: string;
  namespaceId: number;
} | null {
  try {
    const value: unknown = JSON.parse(key);
    if (!Array.isArray(value) || value.length !== 2) return null;
    const [namespaceId, account] = value;
    return Number.isSafeInteger(namespaceId) &&
      (namespaceId as number) >= 0 &&
      typeof account === 'string' &&
      account.length > 0
      ? {
          account,
          namespaceId: namespaceId as number,
        }
      : null;
  } catch {
    return null;
  }
}
type ConversationItemBase = {
  /** Avatar profile revision for the peer in P2P or the group itself. */
  profileRev: number;
  visible?: boolean;
  /** Account-scoped thread-feed coordinate. Present on every visible list item and authoritative for ordering. */
  threadFeedId?: number;
  threadId: number;
  /** Immutable namespace owning this thread's publisher coordinate space. */
  publisherNamespaceId: number;
  /** Subject account: the peer in P2P, the group address in GROUP. */
  account: string;
  /** Display mirror of the selected profile revision; not persisted in thread rows. */
  profile: ThreadProfileSlot;
  /** Viewer home namespace in the group origin's space, never a receiver-local namespace. */
  selfMentionNamespaceId: number | null;
  role: 'OWNER' | 'ADMIN' | 'MEMBER' | null;
  lastMessageAt: number | null;
  /** Durable server message ceiling; independent from the evictable local message cache. */
  messageEndSeq: number;
  /** Latest server-advertised Group Meta target; null for P2P. */
  groupMetaFeedEndId: string | null;
  muted: boolean;
  blocked?: boolean;
  pinned: boolean;
  pinnedAt: number | null;
  alias?: string | null;
  conversationState?: 'ACTIVE' | 'READ_ONLY';
  lastReadSeq?: number | null;
  announcementReadFeedId?: number;
  unreadCount: number;
  // Latest-message preview state is derived from message catch-up and the local message cache.
  lastMessagePreview?: string | null;
  lastMessageSenderAccount?: string | null;
  lastMessageSenderNamespaceId?: number | null;
  /** Distinct mention kinds among the server's bounded unread sample. */
  mentionUnread: Array<'all' | 'me'>;
  /** Manager-only join-application projection coordinates from the thread head. */
  joinRequestEndFeedId?: number;
  /** -1 disables manager attention; zero is the pre-first-application position. */
  joinRequestReadFeedId?: number;
  groupInviteEndFeedId?: number;
};

export type ConversationItem = ConversationItemBase &
  (
    | {
        type: 'P2P';
      }
    | {
        type: 'GROUP';
        /** Group-owned state; mirrors the dedicated group_meta row. */
        meta: GroupMetaSlot;
      }
  );

export type P2PConversationItem = Extract<ConversationItem, { type: 'P2P' }>;
export type GroupConversationItem = Extract<
  ConversationItem,
  { type: 'GROUP' }
>;

/** Only fields explicitly supplied by a local operation may be persisted.
 * Server feed coordinates and group/profile content are not writable here. */
export interface LocalThreadPatch {
  muted?: boolean;
  pinned?: boolean;
  pinnedAt?: number | null;
  blocked?: boolean;
  conversationState?: 'ACTIVE' | 'READ_ONLY';
  announcementReadFeedId?: number;
  joinRequestReadFeedId?: number;
}

/** Display and group-state patches keep their ownership boundaries explicit. */
export interface GroupThreadPatch {
  profile?: Partial<ThreadProfileSlot>;
  meta?: Partial<GroupMetaSlot>;
  role?: GroupConversationItem['role'];
}

type ThreadInput<T extends ConversationItem> = Pick<
  T,
  'threadId' | 'account' | 'publisherNamespaceId' | 'profileRev'
> &
  Partial<Omit<T, 'type' | 'profile' | 'meta'>> & {
    profile?: ThreadProfileSlot;
  };

type GroupThreadInput = ThreadInput<GroupConversationItem> & {
  meta?: Partial<GroupMetaSlot>;
};

/** Construct the canonical local projection for a newly activated, empty P2P thread. */
export function createP2PConversation(
  input: ThreadInput<P2PConversationItem>,
): P2PConversationItem {
  const profile: ThreadProfileSlot = {
    name: '',
    bio: '',
    avatarDigest: null,
    ...input.profile,
  };
  return {
    selfMentionNamespaceId: null,
    type: 'P2P',
    groupMetaFeedEndId: null,
    role: null,
    lastMessageAt: null,
    messageEndSeq: 0,
    muted: false,
    blocked: false,
    pinned: false,
    pinnedAt: null,
    conversationState: 'ACTIVE',
    lastReadSeq: null,
    unreadCount: 0,
    mentionUnread: [],
    lastMessagePreview: null,
    lastMessageSenderAccount: null,
    lastMessageSenderNamespaceId: null,
    ...input,
    profile,
  };
}

/** Initial Meta state before any group feed page has been applied. */
export function createGroupMeta(): GroupMetaSlot {
  return {
    memberCount: 0,
    groupMetaFeedId: '0',
    announcementFeedId: null,
    announcementText: null,
    announcementCreatedAt: null,
    announcementOriginCreatedAt: null,
    recoveryThrough: null,
    recoveryAnnouncementFeedId: null,
    recoveryAnnouncementText: null,
    recoveryAnnouncementCreatedAt: null,
    recoveryAnnouncementOriginCreatedAt: null,
  };
}

/** Construct the canonical local projection for an empty group thread. */
export function createGroupConversation(
  input: GroupThreadInput,
): GroupConversationItem {
  const meta = { ...createGroupMeta(), ...input.meta };
  const profile: ThreadProfileSlot = {
    name: '',
    bio: '',
    avatarDigest: null,
    ...input.profile,
  };
  return {
    selfMentionNamespaceId: input.publisherNamespaceId === 0 ? 0 : null,
    type: 'GROUP',
    groupMetaFeedEndId: '0',
    role: null,
    lastMessageAt: null,
    messageEndSeq: 0,
    muted: false,
    blocked: false,
    pinned: false,
    pinnedAt: null,
    conversationState: 'ACTIVE',
    lastReadSeq: null,
    unreadCount: 0,
    mentionUnread: [],
    lastMessagePreview: null,
    lastMessageSenderAccount: null,
    lastMessageSenderNamespaceId: null,
    ...input,
    profile,
    meta,
  };
}

/** A conversation label prefers the remark and cached profile name. A cache
 * miss still has an identity: display the account rather than a blank label. */
export function displayThreadName(t: ConversationItem): string {
  if (t.alias) return t.alias;
  return t.profile.name?.trim() || t.account;
}

export function displayUserName(u: { name?: string | null }): string {
  return u.name ?? '';
}

/** A user's login address. Local users display the account verbatim; only federated identities append
 *  the server domain with `@` (account@domain). */
export function displayUserAccount(u: {
  account?: string | null;
  domain?: string | null;
  namespaceId?: number | null;
  profileNamespaceId?: number | null;
}): string {
  const account = u.account ?? '';
  const namespaceId = u.profileNamespaceId ?? u.namespaceId;
  return namespaceId === 0 || !u.domain ? account : `${account}@${u.domain}`;
}

export type PersonalQuotaCategory = 'messages' | 'files' | 'requests';

/** Per-user quota breaker snapshot (msg cnt / file cnt / file total size). `fileBytes` is a decimal string
 *  because file-total-size is a backend bigint. */
interface PersonalQuotaBreaker {
  tripped: boolean;
  trippedDims: Array<'msg' | 'file' | 'fileBytes'>;
  msg: { count: number; limit: number };
  file: { count: number; limit: number };
  fileBytes: { bytes: string; limit: number };
}

export interface PersonalQuotaState {
  usage: Record<PersonalQuotaCategory, { count: number; limit: number }>;
  breaker: PersonalQuotaBreaker;
  resetAt: number;
}

type MessageThreadType = ConversationItem['type'];

// Envelope generic (the generated ApiResult.data is unknown and cannot replace this)
export interface StandardResponse<T = unknown> {
  code: number;
  message: string;
  /**
   * Stable i18n key carried by the backend for user-facing statuses that `code` alone cannot disambiguate
   * (e.g. friend-request success variants, all code 0). When present, `translateBizResult` localizes via
   * this and falls back to `message`. Error statuses are localized by numeric `code` (see biz-code.ts).
   */
  messageKey?: string;
  data?: T;
  /** Paginated endpoints return this when another page exists in the requested direction. */
  hasMore?: boolean;
  /** Total visible search matches, independent of the current page cursor. */
  totalCount?: number;
  /** True when this page actually reached the requested truncateSeq boundary. */
  truncated?: boolean;
}

export interface DeletedMessageItem {
  deletionSeq: number;
  threadId: number;
  messageSeq: number;
  type: MessageTomb['deletionType'];
  createdAt: number;
  updatedAt: number;
}

export type ThreadListRecord = ConversationItem;
